// TH16 v1.00a types used by this card, copied from transcribe/th16/touhou-bullets.ecl.
// type 10 (SHARD) reuses the verified TH18 type-10 slot; colors 0-15 are valid.
const TH16_SHARD: int = 512;

// TH16 v1.00a Extra — final boss 3rd non-spell.
// Source: st07bs.ecl.txt Boss3 304-363; dependency Boss3_at 365-388.
// Card clock: 120-frame shell buffer, then the 180 frames of source entry
// waits, then the 320-frame source loop. The 3600-frame interrupt window stops
// the main task 60 frames into the post-B wait of the 11th cycle.

const TIME_LIMIT: int = 3724;
const OPENING_BUFFER: int = 120;
const SRC_WINDOW: int = 3600;

// ---- source Boss3_at -------------------------------------------------------
// etAim(0,3) fixed ring, etCount(0,2,3) 2 ways x 3 layers, spread always 0.
// Each wave is the same line of 6 bullets: base and base+180deg for speeds
// 4 / 3.5 / 3. etSprite(10,8) is type 10 SHARD, color 8.
// etDist(32) plus the ANIM(2,a=1) birth retreat 4*speed leaves a net birth
// distance of 32-4*speed = 16/18/20 px along each bullet's own angle.
sub shard_pair(base: angle, mx: fx, my: fx, speed: fx, net: fx) {
    var c: fx = cos(base);
    var s: fx = sin(base);
    _ = fire(TH16_SHARD, 8, mx + net * c, my + net * s, speed, base, none, none);
    _ = fire(TH16_SHARD, 8, mx - net * c, my - net * s, speed, base + 180deg, none, none);
}
sub shard_wave(base: angle) {
    // etOffset(0, 0, -24): muzzle follows the boss every wave.
    var mx: fx = $self_x;
    var my: fx = $self_y - 24fx;
    shard_pair(base, mx, my, 4fx, 16fx);   // layer 0: etSpeed endpoints 4 -> 3
    shard_pair(base, mx, my, 3.5fx, 18fx); // layer 1
    shard_pair(base, mx, my, 3fx, 20fx);   // layer 2
}
async sub shard_ring(step: angle) {
    // %C = %ANGLE_PLAYER is sampled once when the async call starts.
    var base: angle = aim_player();
    for k in 0..100 {
        shard_wave(base);
        base = base + step; // 0.13962634 rad = 8 deg, sign from the call site
        wait(3);
    }
}

// ---- source moveRand(60,4,1.9) under moveLimit(0,128,240,64) ---------------
// movement.md recipe: direction is sampled once from the current position and
// player x; per-tick speed is 1.9*(60-k)/60; position is clamped (no bounce)
// to the full limit box x +-120, y 96..160. The direction inner box is a
// quarter of the limit: x +-60, y 112..144.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx * 1.9fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; } // source normalizes only this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard with epsilon 0.05 rad (522 BAM).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// ---- source Boss3 entry ----------------------------------------------------
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // Boss(): setHitbox(48,48), circle radius 24
    set_hurtbox(20fx); // Boss(): setHurtbox(40,40), circle radius 20

    // moveVel/moveVelTime/movePosTime(0,...) only clear the previous card's
    // motion; this independent card starts at the recenter target, so the
    // 60-frame move to (0,128) is zero distance and inherits no velocity.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    card_wait(120); // source wait(120) overlaps the move
    card_wait(60);  // moveLimit(0,128,240,64) is applied per tick above

    for c in 0..10 {
        spawn shard_ring(8deg);   // Boss3_at(+0.13962634f, +0.008726646f) async
        card_wait(100);
        card_move_rand();         // wait(100); moveRand(60,4,1.9); wait(60)
        card_wait(60);
        spawn shard_ring(-8deg);  // Boss3_at(-0.13962634f, -0.008726646f) async
        card_wait(100);
        card_move_rand();
        card_wait(60);
    }
    // 11th cycle cut by the 3600-frame interrupt: A at 3380, move, B at 3540,
    // then the source's wait(100) is interrupted after 60 frames.
    spawn shard_ring(8deg);
    card_wait(100);
    card_move_rand();
    card_wait(60);
    spawn shard_ring(-8deg);
    card_wait(60);
}

// ---- training shell (validation.md) ----------------------------------------
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 14500, 0, 0, 0, boss_main);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
